mapper.select:
SELECT m.pi, MAX(m.customer_code) customer_code, COUNT(DISTINCT m.bill_no) bills, GROUP_CONCAT(DISTINCT m.org_code ORDER BY m.org_code) orgs, SUM(FLOOR(m.qty)) total_qty, SUM(COALESCE(c.gen_count, 0)) gen_sum, SUM(GREATEST(FLOOR(m.qty) - COALESCE(c.own_generated, 0), 0)) quota, MAX(m.bill_no) last_bill, MAX(m.modify_time) modify_time FROM sn_prd_mo m LEFT JOIN sn_line_count c ON c.bill_no = m.bill_no AND c.seq = m.seq WHERE m.pi <> ''
AND 1=0 AND m.org_code IN #{f}
AND m.pi IN (SELECT x.pi FROM sn_prd_mo x WHERE x.pi LIKE #{like} OR x.bill_no LIKE #{like} OR x.po LIKE #{like} OR x.customer_code LIKE #{like} OR x.material_code LIKE #{like})
GROUP BY m.pi
ORDER BY MAX(m.modify_time) IS NULL, MAX(m.modify_time) DESC, last_bill DESC ORDER BY last_bill DESC
LIMIT #{limit}

